window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b536c40eb0baa15a"]={"versions": [{"id": "FIG-b536c40eb0baa15a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Sequenz- und Interaktionsdiagramm mit schematischer Speicherabbildung im Kontext der AUTOSAR Classic Platform. Es visualisiert das Zusammenspiel zwischen externem Diagnosetester, Diagnostic Communication Manager (DCM) und Diagnostic Event Manager (DEM) bei der Abfrage von DTC-Snapshot-Datensatz-Identifikatoren (UDS-Dienst 0x19 03) sowie die interne Zuordnung im Ereignisspeicher des DEM.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Tester</strong>: Externer Diagnosetester; sendet UDS-Anfragen und empfängt UDS-Antworten.</li>\n<li><strong>DCM</strong>: Diagnostic Communication Manager; verarbeitet Diagnoseanfragen und iteriert über Filterergebnisse des DEM.</li>\n<li><strong>DEM</strong>: Diagnostic Event Manager; verwaltet den primären Ereignisspeicher (<code>Event memory</code>) mit Freeze-Frame-Datensätzen geordnet nach DTCs und absoluten Record-Nummern.</li>\n<li><strong>UDS-Schnittstelle (Tester <-> DCM)</strong>:</li>\n<li><code>Request: $19 $03 (no parameter)</code>: UDS-Dienst <code>ReadDTCInformation</code>, Subfunktion <code>reportDTCSnapshotRecordIdentification</code>.</li>\n<li><code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>: Positive UDS-Antwort mit Liste von DTCs und zugehörigen RecordNumbers.</li>\n<li><strong>BswM/C-API (DCM -> DEM)</strong>:</li>\n<li><code>Dem_DcmSetFreezeRecordFilter</code>: Initialisiert den Filter für Freeze-Frame-Datensätze; liefert als Rückgabewert <code>NumberOfFilteredRecords</code>.</li>\n<li><code>Dem_DcmGetNextFilteredRecord</code>: Ruft sukzessive den nächsten gefilterten Datensatz ab; liefert als Rückgabewert den zugehörigen <code>DTC</code>.</li>\n<li><strong>Datenstrukturen</strong>:</li>\n<li><code>Event memory</code>: Tabellarische Zuordnung von DTCs (z. B. DTC1, DTC2, free) zu nummerierten Freeze-Frame-Datensätzen (z. B. Datensätze 1, 2, 4 belegt; 3, 5, 6, 7, 8, 9 frei).</li>\n<li><code>Example</code>: Exemplarische Zuordnung absoluter Datensatznummern (1 bis 10) zu <code>DTC1</code>, <code>NoDTC ForRecord</code>, <code>DTC2</code> und <code>Wrong Record</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanfrage <code>Request: $19 $03 (no parameter)</code> an den DCM.</li>\n<li>Der DCM ruft die Funktion <code>Dem_DcmSetFreezeRecordFilter</code> am DEM auf.</li>\n<li>Der DEM antwortet synchron/über den Rückgabewert mit <code>NumberOfFilteredRecords</code>.</li>\n<li>Der DCM führt eine interne Iterationsschleife aus, gesteuert durch die empfangene Anzahl <code>NumberOfFilteredRecords</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb der Schleife ruft der DCM wiederholt <code>Dem_DcmGetNextFilteredRecord</code> am DEM auf.</li>\n<li>Der DEM liefert pro Aufruf den jeweiligen Rückgabewert <code>DTC</code> (bzw. zugehörige Record-Informationen) zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss der Filterabfragen stellt der DCM die UDS-Antwort zusammen und sendet <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code> zurück an den externen Tester.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Datensatznummern müssen absolut sein (<code>RecordNumbers must be absolute</code>), d. h. systemweit eindeutig über die Freeze Frames bzw. den DEM-Ereignisspeicher adressiert.</li>\n<li>Bei der Auswertung von <code>Dem_DcmSetFreezeRecordFilter</code> steuert <code>NumberOfFilteredRecords</code> die exakte Anzahl der nachfolgenden Aufrufe von <code>Dem_DcmGetNextFilteredRecord</code>.</li>\n<li>Datensätze ohne gültigen DTC (<code>NoDTC ForRecord</code>) oder ungültige Datensätze (<code>Wrong Record</code>) müssen vom DCM bzw. DEM entsprechend dem Standardverhalten für gefilterte Datensätze behandelt werden.</li>\n</ul>"}, {"id": "FIG-c8d2f9144eeeae87", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Sequenz- und Interaktionsdiagramm mit schematischer Speicherabbildung im Kontext der AUTOSAR Classic Platform. Es visualisiert das Zusammenspiel zwischen externem Diagnosetester, Diagnostic Communication Manager (DCM) und Diagnostic Event Manager (DEM) bei der Abfrage von DTC-Snapshot-Datensatz-Identifikatoren (UDS-Dienst 0x19 03) sowie die interne Zuordnung im Ereignisspeicher des DEM.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Tester</strong>: Externer Diagnosetester; sendet UDS-Anfragen und empfängt UDS-Antworten.</li>\n<li><strong>DCM</strong>: Diagnostic Communication Manager; verarbeitet Diagnoseanfragen und iteriert über Filterergebnisse des DEM.</li>\n<li><strong>DEM</strong>: Diagnostic Event Manager; verwaltet den primären Ereignisspeicher (<code>Event memory</code>) mit Freeze-Frame-Datensätzen geordnet nach DTCs und absoluten Record-Nummern.</li>\n<li><strong>UDS-Schnittstelle (Tester <-> DCM)</strong>:</li>\n<li><code>Request: $19 $03 (no parameter)</code>: UDS-Dienst <code>ReadDTCInformation</code>, Subfunktion <code>reportDTCSnapshotRecordIdentification</code>.</li>\n<li><code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>: Positive UDS-Antwort mit Liste von DTCs und zugehörigen RecordNumbers.</li>\n<li><strong>BswM/C-API (DCM -> DEM)</strong>:</li>\n<li><code>Dem_DcmSetFreezeRecordFilter</code>: Initialisiert den Filter für Freeze-Frame-Datensätze; liefert als Rückgabewert <code>NumberOfFilteredRecords</code>.</li>\n<li><code>Dem_DcmGetNextFilteredRecord</code>: Ruft sukzessive den nächsten gefilterten Datensatz ab; liefert als Rückgabewert den zugehörigen <code>DTC</code>.</li>\n<li><strong>Datenstrukturen</strong>:</li>\n<li><code>Event memory</code>: Tabellarische Zuordnung von DTCs (z. B. DTC1, DTC2, free) zu nummerierten Freeze-Frame-Datensätzen (z. B. Datensätze 1, 2, 4 belegt; 3, 5, 6, 7, 8, 9 frei).</li>\n<li><code>Example</code>: Exemplarische Zuordnung absoluter Datensatznummern (1 bis 10) zu <code>DTC1</code>, <code>NoDTC ForRecord</code>, <code>DTC2</code> und <code>Wrong Record</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanfrage <code>Request: $19 $03 (no parameter)</code> an den DCM.</li>\n<li>Der DCM ruft die Funktion <code>Dem_DcmSetFreezeRecordFilter</code> am DEM auf.</li>\n<li>Der DEM antwortet synchron/über den Rückgabewert mit <code>NumberOfFilteredRecords</code>.</li>\n<li>Der DCM führt eine interne Iterationsschleife aus, gesteuert durch die empfangene Anzahl <code>NumberOfFilteredRecords</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb der Schleife ruft der DCM wiederholt <code>Dem_DcmGetNextFilteredRecord</code> am DEM auf.</li>\n<li>Der DEM liefert pro Aufruf den jeweiligen Rückgabewert <code>DTC</code> (bzw. zugehörige Record-Informationen) zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss der Filterabfragen stellt der DCM die UDS-Antwort zusammen und sendet <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code> zurück an den externen Tester.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Datensatznummern müssen absolut sein (<code>RecordNumbers must be absolute</code>), d. h. systemweit eindeutig über die Freeze Frames bzw. den DEM-Ereignisspeicher adressiert.</li>\n<li>Bei der Auswertung von <code>Dem_DcmSetFreezeRecordFilter</code> steuert <code>NumberOfFilteredRecords</code> die exakte Anzahl der nachfolgenden Aufrufe von <code>Dem_DcmGetNextFilteredRecord</code>.</li>\n<li>Datensätze ohne gültigen DTC (<code>NoDTC ForRecord</code>) oder ungültige Datensätze (<code>Wrong Record</code>) müssen vom DCM bzw. DEM entsprechend dem Standardverhalten für gefilterte Datensätze behandelt werden.</li>\n</ul>"}, {"id": "FIG-702df257c71620e0", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Sequenz- und Interaktionsdiagramm mit schematischer Speicherabbildung im Kontext der AUTOSAR Classic Platform. Es visualisiert das Zusammenspiel zwischen externem Diagnosetester, Diagnostic Communication Manager (DCM) und Diagnostic Event Manager (DEM) bei der Abfrage von DTC-Snapshot-Datensatz-Identifikatoren (UDS-Dienst 0x19 03) sowie die interne Zuordnung im Ereignisspeicher des DEM.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Tester</strong>: Externer Diagnosetester; sendet UDS-Anfragen und empfängt UDS-Antworten.</li>\n<li><strong>DCM</strong>: Diagnostic Communication Manager; verarbeitet Diagnoseanfragen und iteriert über Filterergebnisse des DEM.</li>\n<li><strong>DEM</strong>: Diagnostic Event Manager; verwaltet den primären Ereignisspeicher (<code>Event memory</code>) mit Freeze-Frame-Datensätzen geordnet nach DTCs und absoluten Record-Nummern.</li>\n<li><strong>UDS-Schnittstelle (Tester <-> DCM)</strong>:</li>\n<li><code>Request: $19 $03 (no parameter)</code>: UDS-Dienst <code>ReadDTCInformation</code>, Subfunktion <code>reportDTCSnapshotRecordIdentification</code>.</li>\n<li><code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>: Positive UDS-Antwort mit Liste von DTCs und zugehörigen RecordNumbers.</li>\n<li><strong>BswM/C-API (DCM -> DEM)</strong>:</li>\n<li><code>Dem_SetFreezeRecordFilter</code>: Initialisiert den Filter für Freeze-Frame-Datensätze; liefert als Rückgabewert <code>NumberOfFilteredRecords</code>.</li>\n<li><code>Dem_GetNextFilteredRecord</code>: Ruft sukzessive den nächsten gefilterten Datensatz ab; liefert als Rückgabewert den zugehörigen <code>DTC</code>.</li>\n<li><strong>Datenstrukturen</strong>:</li>\n<li><code>Event memory</code>: Tabellarische Zuordnung von DTCs (z. B. DTC1, DTC2, free) zu nummerierten Freeze-Frame-Datensätzen (z. B. Datensätze 1, 2, 4 belegt; 3, 5, 6, 7, 8, 9 frei).</li>\n<li><code>Example</code>: Exemplarische Zuordnung absoluter Datensatznummern (1 bis 10) zu <code>DTC1</code>, <code>NoDTC ForRecord</code>, <code>DTC2</code> und <code>Wrong Record</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanfrage <code>Request: $19 $03 (no parameter)</code> an den DCM.</li>\n<li>Der DCM ruft die Funktion <code>Dem_SetFreezeRecordFilter</code> am DEM auf.</li>\n<li>Der DEM antwortet synchron/über den Rückgabewert mit <code>NumberOfFilteredRecords</code>.</li>\n<li>Der DCM führt eine interne Iterationsschleife aus, gesteuert durch die empfangene Anzahl <code>NumberOfFilteredRecords</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Innerhalb der Schleife ruft der DCM wiederholt <code>Dem_GetNextFilteredRecord</code> am DEM auf.</li>\n<li>Der DEM liefert pro Aufruf den jeweiligen Rückgabewert <code>DTC</code> (bzw. zugehörige Record-Informationen) zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Abschluss der Filterabfragen stellt der DCM die UDS-Antwort zusammen und sendet <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code> zurück an den externen Tester.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Datensatznummern müssen absolut sein (<code>RecordNumbers must be absolute</code>), d. h. systemweit eindeutig über die Freeze Frames bzw. den DEM-Ereignisspeicher adressiert.</li>\n<li>Bei der Auswertung von <code>Dem_DcmSetFreezeRecordFilter</code> steuert <code>NumberOfFilteredRecords</code> die exakte Anzahl der nachfolgenden Aufrufe von <code>Dem_DcmGetNextFilteredRecord</code>.</li>\n<li>Datensätze ohne gültigen DTC (<code>NoDTC ForRecord</code>) oder ungültige Datensätze (<code>Wrong Record</code>) müssen vom DCM bzw. DEM entsprechend dem Standardverhalten für gefilterte Datensätze behandelt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-b536c40eb0baa15a", "to": "FIG-c8d2f9144eeeae87", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c8d2f9144eeeae87", "to": "FIG-702df257c71620e0", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>API-Funktionsaufruf geändert: <code>Dem_DcmSetFreezeRecordFilter</code> zu <code>Dem_SetFreezeRecordFilter</code></li>\n<li>API-Funktionsaufruf geändert: <code>Dem_DcmGetNextFilteredRecord</code> zu <code>Dem_GetNextFilteredRecord</code></li>\n</ul>"}]};
